nix_evaluation_command_argv:
let
  flake = builtins.getFlake "path:/workspace/vps-infrastructure";
  config = (flake.inputs.nixpkgs.lib.nixosSystem {
    system = "x86_64-linux";
    modules = [ flake.nixosModules.vpsPreparation ];
  }).config;
in {
  publicKeys = config.services.mrjamInventory.publicKeys;
  inventoryDisabled = !config.services.mrjamInventory.enable;
  rustDisabled = !config.services.mrjamRust.enable;
  forgejoDisabled = !config.services.mrjamForgejo.enable;
  noInventoryAccount = !(config.users.users ? mrjam-inventory);
  noInventoryGroup = !(config.users.groups ? mrjam-inventory);
  noAuthorizedKeysFile = !(config.environment.etc ? "ssh/mrjam-inventory-authorized-keys");
  noInventorySshMatch = !(flake.inputs.nixpkgs.lib.hasInfix "Match User mrjam-inventory" config.services.openssh.extraConfig);
  noProductionHost = !(flake ? nixosConfigurations);
  identityUnspecified = config.services.mrjamInventory.adoption.uid == null && config.services.mrjamInventory.adoption.gid == null;
}
